import java.util.NavigableMap;
import java.util.TreeMap;

public class IpRoutingTable {
    // Stores subnet starting IP as long -> Gateway Name
    private final NavigableMap<Long, String> routes = new TreeMap<>();

    public void addRoute(long ipStart, String gateway) {
        routes.put(ipStart, gateway);
    }

    public String resolveGateway(long targetIp) {
        // floorKey finds the greatest route address <= targetIp
        Long baseIp = routes.floorKey(targetIp);
        if (baseIp == null) {
            return "DEFAULT_GATEWAY";
        }
        return routes.get(baseIp);
    }

    public static void main(String[] args) {
        IpRoutingTable router = new IpRoutingTable();
        router.addRoute(167772160L, "US_EAST_GATEWAY"); // 10.0.0.0
        router.addRoute(2886729728L, "EU_CENTRAL_GATEWAY"); // 172.16.0.0
        router.addRoute(3232235520L, "ASIA_PACIFIC_GATEWAY"); // 192.168.0.0

        long incomingTraffic = 167772260L; // 10.0.0.100
        System.out.println("Routed to: " + router.resolveGateway(incomingTraffic));
    }
}

