import java.util.TreeMap;
import java.util.Map;

public class TaxService {
    public static double getTaxRate(TreeMap<Double, Double> brackets, double income) {
        if (brackets == null || income < 0) return 0.0;
        Map.Entry<Double, Double> entry = brackets.floorEntry(income);
        return entry != null ? entry.getValue() : 0.0;
    }
}

