import java.util.TreeMap;
import java.util.Map;

public class EventTimeline {
    public static String findPrecedingEvent(TreeMap<Long, String> events, long queryTime) {
        if (events == null) return "NONE";
        Map.Entry<Long, String> entry = events.lowerEntry(queryTime);
        return entry != null ? entry.getValue() : "NONE";
    }
